    #[test]
    fn live_parameter_replacement_controls_command_line_and_standard_handles_all_abis() {
        use crate::user::windows::arch::WinArch;
        for arch in WinArch::ALL {
            let image: &[u8] = match arch {
                WinArch::X86 => {
                    include_bytes!("../../../../tests/fixtures/user/windows/bin/x86/smoke.exe")
                }
                WinArch::X64 => {
                    include_bytes!("../../../../tests/fixtures/user/windows/bin/x64/smoke.exe")
                }
                WinArch::Arm64 => {
                    include_bytes!("../../../../tests/fixtures/user/windows/bin/arm64/smoke.exe")
                }
            };
            let mut config = WindowsConfig::new("old-command.exe", vec![]);
            config.seed = Some(1);
            config.arena_bytes = 64 << 20;
            let mut process = WindowsProcess::spawn_image(config, image.to_vec()).unwrap();
            let p = process.state_mut();
            let o = offsets(arch);
            let original = p.params;
            let header = p.space.bytes(original, o.pp_size as usize).unwrap();
            let replacement = p
                .heaps
                .alloc(&mut p.vm, p.process_heap, o.pp_size + 128, true)
                .unwrap();
            p.space.wr(replacement, &header).unwrap();
            let command = "new-command.exe /d /c exit 37";
            let buffer = replacement + o.pp_size;
            p.space
                .put_wstr(buffer, &command.encode_utf16().collect::<Vec<_>>())
                .unwrap();
            p.space
                .wptr(replacement + o.pp_command_line + o.ptr, o.ptr, buffer)
                .unwrap();
            p.space
                .wptr(p.peb + o.peb_process_parameters, o.ptr, replacement)
                .unwrap();
            p.space
                .wr(original, &vec![0xDD; o.pp_size as usize])
                .unwrap();
            let tid = *p.threads.keys().next().unwrap();
            let mut thread = p.threads.remove(&tid).unwrap();
            let sp = thread.cpu.sp();
            let api = |name| {
                EXPORTS
                    .iter()
                    .find_map(|export| match &export.item {
                        Item::Func(api) if api.name == name => Some(api),
                        _ => None,
                    })
                    .unwrap()
            };
            let mut c = Ctx {
                p,
                t: &mut thread,
                api: api("GetCommandLineW"),
                entry_pc: 0,
                entry_sp: sp,
                ret_addr: 0,
                cursor: sp,
            };
            let integer = |flow| match flow {
                Flow::Ret(Value::Int(value)) => value,
                _ => panic!("integer API result expected"),
            };
            assert_eq!(integer(command_line_w(&mut c).unwrap()), buffer);
            c.api = api("GetCommandLineA");
            let narrow = integer(command_line_a(&mut c).unwrap());
            assert_eq!(
                c.mem().bytes(narrow, command.len() + 1).unwrap(),
                [command.as_bytes(), &[0]].concat()
            );
            for (index, (selector, offset)) in [
                (-10i32, o.pp_std_input),
                (-11, o.pp_std_output),
                (-12, o.pp_std_error),
            ]
            .into_iter()
            .enumerate()
            {
                let handle = 0x1234_0000 + index as u64;
                c.api = api("SetStdHandle");
                for (index, value) in [u64::from(selector as u32), handle].into_iter().enumerate() {
                    match arch {
                        WinArch::X86 => c
                            .mem()
                            .w32(sp + 4 + index as u64 * 4, value as u32)
                            .unwrap(),
                        WinArch::X64 => c.t.cpu.set_gpr([1, 2][index], value),
                        WinArch::Arm64 => c.t.cpu.set_gpr(index, value),
                    }
                }
                assert_eq!(integer(set_std_handle(&mut c).unwrap()), 1);
                assert_eq!(c.read_ptr(replacement + offset).unwrap(), handle);
                c.api = api("GetStdHandle");
                assert_eq!(integer(get_std_handle(&mut c).unwrap()), handle);
            }
            c.write_ptr(c.p.peb + o.peb_process_parameters, 0).unwrap();
            c.api = api("GetCommandLineW");
            assert!(matches!(command_line_w(&mut c), Err(ApiErr::Fault(_))));
        }
    }

    fn command_line_trial(
        arch: crate::user::windows::arch::WinArch,
        command: &str,
        expected: &[u8],
    ) {
        use crate::user::windows::arch::WinArch;
        let image: &[u8] = match arch {
            WinArch::X86 => {
                include_bytes!("../../../../tests/fixtures/user/windows/bin/x86/smoke.exe")
            }
            WinArch::X64 => {
                include_bytes!("../../../../tests/fixtures/user/windows/bin/x64/smoke.exe")
            }
            WinArch::Arm64 => {
                include_bytes!("../../../../tests/fixtures/user/windows/bin/arm64/smoke.exe")
            }
        };
        let mut config = WindowsConfig::new("command-line-test.exe", vec![]);
        config.command_line = Some(command.into());
        config.seed = Some(1);
        config.arena_bytes = 64 << 20;
        let mut process = WindowsProcess::spawn_image(config, image.to_vec()).unwrap();
        let p = process.state_mut();
        let tid = *p.threads.keys().next().unwrap();
        let mut t = p.threads.remove(&tid).unwrap();
        let api = EXPORTS
            .iter()
            .find_map(|export| match &export.item {
                Item::Func(api) if api.name == "GetCommandLineA" => Some(api),
                _ => None,
            })
            .unwrap();
        let sp = t.cpu.sp();
        let mut c = Ctx {
            p,
            t: &mut t,
            api,
            entry_pc: 0,
            entry_sp: sp,
            ret_addr: 0,
            cursor: sp,
        };
        c.set_last_error(0x1234_5678).unwrap();
        let pointer = |flow| match flow {
            Flow::Ret(Value::Int(pointer)) => pointer,
            _ => panic!("GetCommandLineA must return a pointer"),
        };
        let field = c.p.current_parameters().unwrap() + offsets(arch).pp_command_line + c.psize();
        let wide = c.read_ptr(field).unwrap();
        let before = c.p.heaps.blocks(c.p.process_heap);
        c.write_ptr(field, 0).unwrap();
        assert!(matches!(
            command_line_a(&mut c),
            Err(crate::user::windows::hle::ApiErr::Fault(_))
        ));
        assert!(c.p.ansi_command_line.is_none());
        assert_eq!(c.p.heaps.blocks(c.p.process_heap), before);
        c.write_ptr(field, wide).unwrap();
        let heap = c.p.process_heap;
        let _pad =
            c.p.heaps
                .alloc(&mut c.p.vm, heap, 2 * PAGE_SIZE, false)
                .unwrap();
        let _lower = c.p.heaps.alloc(&mut c.p.vm, heap, 16, false).unwrap();
        let target =
            c.p.heaps
                .alloc(&mut c.p.vm, heap, expected.len() as u64 + 1, false)
                .unwrap();
        let _upper = c.p.heaps.alloc(&mut c.p.vm, heap, 16, false).unwrap();
        assert_ne!(
            target / PAGE_SIZE,
            wide / PAGE_SIZE,
            "{arch}: protected target aliases source"
        );
        c.p.heaps.free(heap, target).unwrap();
        let before = c.p.heaps.blocks(heap);
        c.p.vm
            .protect(target, expected.len() as u64 + 1, prot::NOACCESS)
            .unwrap();
        assert!(matches!(
            command_line_a(&mut c),
            Err(crate::user::windows::hle::ApiErr::Fault(fault)) if fault.addr == target && fault.write
        ));
        assert!(c.p.ansi_command_line.is_none());
        assert_eq!(
            c.p.heaps.blocks(heap),
            before,
            "{arch}: failed write leaked a block"
        );
        c.p.vm
            .protect(target, expected.len() as u64 + 1, prot::READWRITE)
            .unwrap();
        let first = pointer(command_line_a(&mut c).unwrap());
        assert_eq!(
            first, target,
            "{arch}: retry did not reuse the rolled-back block"
        );
        assert_eq!(
            c.mem().cstr(first, expected.len() + 1).unwrap(),
            expected,
            "{arch}"
        );
        assert_eq!(
            c.mem().bytes(first + expected.len() as u64, 1).unwrap(),
            [0]
        );
        let blocks = c.p.heaps.blocks(c.p.process_heap);
        let second = pointer(command_line_a(&mut c).unwrap());
        assert_eq!(
            second, first,
            "{arch}: process-owned pointer must be stable"
        );
        assert_eq!(
            c.p.heaps.blocks(c.p.process_heap),
            blocks,
            "{arch}: repeated call allocated"
        );
        assert_eq!(c.last_error().unwrap(), 0x1234_5678);
    }

